To write unit tests for the `MongoServiceCollectionExtensions` class, we need to focus on the `GetStoreOptions` method, particularly the line where `sp.GetService<IEmbeddingGenerator>()` is called. We'll mock the `IServiceProvider` to control the behavior of `GetService`.

Here's a test file that covers the `GetStoreOptions` method:

```csharp
using System;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.SemanticKernel.Connectors.MongoDB;
using Moq;
using Xunit;

namespace Microsoft.Extensions.DependencyInjection.Tests
{
    public class MongoServiceCollectionExtensionsTests
    {
        [Fact]
        public void GetStoreOptions_ReturnsOptionsWithEmbeddingGenerator_WhenEmbeddingGeneratorIsProvided()
        {
            // Arrange
            var mockServiceProvider = new Mock<IServiceProvider>();
            var mockEmbeddingGenerator = new Mock<IEmbeddingGenerator>();
            mockServiceProvider.Setup(sp => sp.GetService(typeof(IEmbeddingGenerator))).Returns(mockEmbeddingGenerator.Object);

            var options = new MongoVectorStoreOptions();

            // Act
            var result = MongoServiceCollectionExtensions.GetStoreOptions(mockServiceProvider.Object, _ => options);

            // Assert
            Assert.NotNull(result);
            Assert.Same(mockEmbeddingGenerator.Object, result.EmbeddingGenerator);
        }

        [Fact]
        public void GetStoreOptions_ReturnsOriginalOptions_WhenEmbeddingGeneratorIsNotProvided()
        {
            // Arrange
            var mockServiceProvider = new Mock<IServiceProvider>();
            mockServiceProvider.Setup(sp => sp.GetService(typeof(IEmbeddingGenerator))).Returns((IEmbeddingGenerator)null);

            var options = new MongoVectorStoreOptions();

            // Act
            var result = MongoServiceCollectionExtensions.GetStoreOptions(mockServiceProvider.Object, _ => options);

            // Assert
            Assert.NotNull(result);
            Assert.Same(options, result);
        }

        [Fact]
        public void GetStoreOptions_ReturnsNewOptionsWithEmbeddingGenerator_WhenEmbeddingGeneratorIsProvidedAndOptionsAreNotNull()
        {
            // Arrange
            var mockServiceProvider = new Mock<IServiceProvider>();
            var mockEmbeddingGenerator = new Mock<IEmbeddingGenerator>();
            mockServiceProvider.Setup(sp => sp.GetService(typeof(IEmbeddingGenerator))).Returns(mockEmbeddingGenerator.Object);

            var options = new MongoVectorStoreOptions { EmbeddingGenerator = new Mock<IEmbeddingGenerator>().Object };

            // Act
            var result = MongoServiceCollectionExtensions.GetStoreOptions(mockServiceProvider.Object, _ => options);

            // Assert
            Assert.NotNull(result);
            Assert.NotSame(options, result);
            Assert.Same(mockEmbeddingGenerator.Object, result.EmbeddingGenerator);
        }
    }
}
```

This test file includes three test cases:
1. **GetStoreOptions_ReturnsOptionsWithEmbeddingGenerator_WhenEmbeddingGeneratorIsProvided**: Verifies that if an `IEmbeddingGenerator` is provided, it is set in the returned options.
2. **GetStoreOptions_ReturnsOriginalOptions_WhenEmbeddingGeneratorIsNotProvided**: Verifies that if no `IEmbeddingGenerator` is provided, the original options are returned.
3. **GetStoreOptions_ReturnsNewOptionsWithEmbeddingGenerator_WhenEmbeddingGeneratorIsProvidedAndOptionsAreNotNull**: Verifies that if an `IEmbeddingGenerator` is provided and the original options are not null, a new set of options with the `IEmbeddingGenerator` is returned.

